-- Vafot chegarasi qoidasini buzgan 21 kartochkani tuzatish.
--
-- MUAMMO. M1 qoidasi: qahramon o'z vafotidan keyingi voqealarni «bilmaydi».
-- Bu kartochkalarda esa qahramon vafotidan keyingi yubiley, muzey va
-- mukofotlarni o'limini tan olmasdan so'zlab berardi (masalan, al-Xorazmiy
-- 1983-yilgi yubileyi haqida). Bazadagi 4 ta to'g'ri namuna allaqachon
-- «Men ...-yilda vafot etganman. Shundan keyin ...» shaklida edi — qolgan
-- 21 tasi shu shaklga keltirildi.
--
-- Matnlar 5 ta qayta yozuvchi va 5 ta adversarial tekshiruvchi agent orqali
-- tayyorlandi: barcha sanalar, raqamlar va nomlar asl kartochkadan aynan
-- saqlangan, faqat o'limni ochiq tan olish qo'shilgan.
--
-- Qo'shimcha: id 143 dagi kirill harflari («пулига») lotinga tuzatildi.

UPDATE fact_cards SET fact_uz = $$Men 867-yilda vafot etganman. Oradan ko'p asrlar o'tib, 1998-yilda tavalludimning 1200 yilligi xalqaro miqyosda nishonlangan va Quva shahrida menga haykal o'rnatilgan. Xotiram shu tarzda yashab kelayotgani meni juda quvontiradi.$$ WHERE id = 190;

UPDATE fact_cards SET fact_uz = $$Men taxminan 1455-yilda tug'ilganman, 1535-yilda esa vafot etganman. Vafotimdan keyin ham nomim unutilmagan — 2020-yilda tavalludimning 565 yilligi nishonlangan.$$ WHERE id = 357;

UPDATE fact_cards SET fact_uz = $$Men 1829-yilda vafot etganman. «Munis ul-ushshoq» devonimga yigirma mingdan ortiq misra she'r jamlaganman — vafotimdan keyin, 1880-yilda, u Xivada chop etilgan.$$ WHERE id = 414;

UPDATE fact_cards SET fact_uz = $$Men 959-yilda vafot etganman, lekin kitobim yashashda davom etgan. Uning arab tilidagi asl nusxasi bizgacha yetib kelmagan. Vafotimdan keyin, 1128-yilda asli Quva shahridan bo'lgan Abu Nasr Ahmad al-Quboviy uni fors tiliga tarjima qilgan va qisqartirgan.$$ WHERE id = 469;

UPDATE fact_cards SET fact_uz = $$Men 959-yilda vafot etganman. Vafotimdan ancha keyin, 1178–1179-yillarda Muhammad ibn Zufar forscha tarjimani yana bir bor qisqartirib bayon qilgan. Shu tariqa kitobim asrlar davomida qayta ko'chirilib, avloddan avlodga o'tgan.$$ WHERE id = 470;

UPDATE fact_cards SET fact_uz = $$Men 959-yilda vafot etganman, ammo kitobim mendan keyin dunyo bo'ylab sayohat qilgan. U 1892-yilda Parijda nashr etilgan, 1897-yilda Toshkentda rus tilida, 1954-yilda Kembrijda ingliz tilida, 1966-yilda esa A. Rasulev tarjimasida o'zbek tilida chop etilgan.$$ WHERE id = 472;

UPDATE fact_cards SET fact_uz = $$Men 1991-yilda vafot etganman. Vafotimdan keyin, 1994-yilda Toshkentdagi uyimda xotira muzeyi tashkil etilgan — u yerda sahna liboslarim, mukofotlarim, suratlar va menga yozilgan maktublar saqlanadi.$$ WHERE id = 545;

UPDATE fact_cards SET fact_uz = $$Men 1938-yilda vafot etganman. Oradan yillar o'tib, 1956-yilda nomim oqlangan. Shundan so'ng asarlarim yana nashr etilib, xalqqa qaytgan.$$ WHERE id = 1451;

UPDATE fact_cards SET fact_uz = $$Men 867-yilda vafot etganman. Vafotimdan ming yildan ziyod vaqt o'tib, 1998-yilda tavalludimning 1200 yilligi keng nishonlangan. Shu munosabat bilan Farg'ona va Quva shaharlarida menga haykallar o'rnatilgan — bu mening 1200 yillik to'yim edi!$$ WHERE id = 1494;

UPDATE fact_cards SET fact_uz = $$Men 850-yilda vafot etganman. Vafotimdan ko'p asrlar keyin, 1983-yilda tavalludimning 1200 yilligi keng nishonlangan. Shu munosabat bilan ona yurtim Xorazmda xotiram uchun haykal o'rnatilgan. Yurtdoshlarim meni unutmagani qalbimni iliqlikka to'ldiradi.$$ WHERE id = 1503;

UPDATE fact_cards SET fact_uz = $$Men 1405-yilda vafot etganman. Oradan asrlar o'tib, 1996-yilda O'zbekistonda tavalludimning 660 yilligi keng nishonlangan va Toshkentda Temuriylar tarixi davlat muzeyi ochilgan. Toshkent, Samarqand va Shahrisabzda haykallarim o'rnatilgan — xalqim meni hamon yodda tutishidan faxrlanaman.$$ WHERE id = 1525;

UPDATE fact_cards SET fact_uz = $$Men 1938-yilda vafot etganman. Oradan yillar o'tib, 1956-yilda nomim rasman oqlangan. Asarlarim esa 1980-yillarning oxiridan boshlab yana kitob bo'lib chiqa boshlagan va o'quvchilarga qaytgan.$$ WHERE id = 1561;

UPDATE fact_cards SET fact_uz = $$Men 1938-yilda vafot etganman. 1991-yilda ijodim Alisher Navoiy nomidagi O'zbekiston Respublikasi Davlat mukofoti bilan taqdirlangan.$$ WHERE id = 1562;

UPDATE fact_cards SET fact_uz = $$Men 870-yilda vafot etganman. Vafotimdan ko'p asrlar o'tib, 1998-yilda Samarqand yaqinidagi qabrim ustida katta yodgorlik majmuasi barpo etilgan. Bugun u yerga dunyoning turli mamlakatlaridan ziyoratchilar keladi.$$ WHERE id = 1649;

UPDATE fact_cards SET fact_uz = $$Men 1231-yilda vafot etganman. Oradan asrlar o'tib, 1999-yilda O'zbekistonda tavalludimning 800 yilligi keng nishonlangan. Xalqim meni shuncha yildan keyin ham eslashi qalbimni iftixorga to'ldiradi.$$ WHERE id = 1678;

UPDATE fact_cards SET fact_uz = $$Men 1231-yilda vafot etganman. Vafotimdan ko'p asrlar keyin, 2000-yilda O'zbekistonda «Jaloliddin Manguberdi» ordeni ta'sis etilgan. Bu orden Vatan himoyasida jasorat ko'rsatgan harbiylarga beriladi — nomim mard askarlar bilan birga yashayotgani men uchun katta sharaf!$$ WHERE id = 1680;

UPDATE fact_cards SET fact_uz = $$Men 1449-yilda vafot etganman. Vafotimdan keyin asrlar o'tib, rasadxonam yer ostida ko'milib qolgan edi. 1908-yilda arxeolog Vasiliy Vyatkin Samarqandda uning qoldiqlarini topdi. Bugun o'sha joyda muzey bor — borib ko'rishing mumkin!$$ WHERE id = 1707;

UPDATE fact_cards SET fact_uz = $$Men 959-yilda vafot etganman. Vafotimdan ko'p asrlar o'tib, kitobim 1966-yilda A. Rasulev tarjimasida o'zbek tilida nashr etilgan. Endi uni sen ham o'z ona tilingda o'qiy olasan.$$ WHERE id = 1743;

UPDATE fact_cards SET fact_uz = $$Men 1408-yilda vafot etganman. Vafotimdan ko'p asrlar keyin, 2001-yilda men yashagan va obidalar qurdirgan Samarqand shahri YUNESKOning Jahon merosi ro'yxatiga kiritilgan. Bibixonim obidalari ham shu merosning bir qismidir — buni eshitsang, men qanchalik quvonishimni tasavvur qil!$$ WHERE id = 1776;

UPDATE fact_cards SET fact_uz = $$Men 1996-yilda vafot etganman. Vafotimdan keyin, 1999-yilda O'zbekistonda Zulfiya nomidagi Davlat mukofoti ta'sis etilgan. U iqtidorli qizlarga beriladi.$$ WHERE id = 1840;

UPDATE fact_cards SET fact_uz = $$Men 1996-yilda vafot etganman. Ammo she'rlarim yashab qolgan: 2015-yilda tavalludimning 100 yilligi O'zbekistonda keng nishonlandi, ijodimga bag'ishlangan tadbirlar o'tkazildi.$$ WHERE id = 1841;


